CREATE TABLE IF NOT EXISTS uat_schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS uat_case_meta (case_id INTEGER PRIMARY KEY REFERENCES cases(id) ON DELETE CASCADE, responsible_unit TEXT NOT NULL DEFAULT '', unit_level1 TEXT NOT NULL DEFAULT '', unit_level2 TEXT NOT NULL DEFAULT '', source_type TEXT NOT NULL DEFAULT '', source_other TEXT NOT NULL DEFAULT '', received_date TEXT NOT NULL DEFAULT '', preliminary_allegation TEXT NOT NULL DEFAULT '', stage TEXT NOT NULL DEFAULT 'case_info', closed_at TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_uat_case_meta_scope ON uat_case_meta(unit_level1,unit_level2,stage);
CREATE TABLE IF NOT EXISTS uat_subjects (id INTEGER PRIMARY KEY AUTOINCREMENT, case_id INTEGER NOT NULL REFERENCES cases(id) ON DELETE CASCADE, sequence_no INTEGER NOT NULL, title_th TEXT NOT NULL DEFAULT '', first_name_th TEXT NOT NULL DEFAULT '', last_name_th TEXT NOT NULL DEFAULT '', position_name TEXT NOT NULL DEFAULT '', employment_type TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(case_id,sequence_no));
CREATE TABLE IF NOT EXISTS uat_subject_status_history (id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id INTEGER NOT NULL REFERENCES uat_subjects(id) ON DELETE CASCADE, status_name TEXT NOT NULL, effective_date TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS uat_case_owners (id INTEGER PRIMARY KEY AUTOINCREMENT, case_id INTEGER NOT NULL REFERENCES cases(id) ON DELETE CASCADE, bma_personal_id TEXT NOT NULL, owner_name TEXT NOT NULL, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_uat_current_owner ON uat_case_owners(case_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS uat_tracks (id INTEGER PRIMARY KEY AUTOINCREMENT, case_id INTEGER NOT NULL REFERENCES cases(id) ON DELETE CASCADE, track_type TEXT NOT NULL CHECK(track_type IN ('fact','discipline_nonserious','discipline_serious')), acknowledged_date TEXT NOT NULL DEFAULT '', first_meeting_date TEXT NOT NULL DEFAULT '', start_date TEXT NOT NULL DEFAULT '', duration_days INTEGER NOT NULL DEFAULT 0, due_date TEXT NOT NULL DEFAULT '', start_override_reason TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(case_id,track_type));
CREATE TABLE IF NOT EXISTS uat_track_subjects (track_id INTEGER NOT NULL REFERENCES uat_tracks(id) ON DELETE CASCADE, subject_id INTEGER NOT NULL REFERENCES uat_subjects(id) ON DELETE CASCADE, PRIMARY KEY(track_id,subject_id));
CREATE TABLE IF NOT EXISTS uat_committee_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, track_id INTEGER NOT NULL REFERENCES uat_tracks(id) ON DELETE CASCADE, event_type TEXT NOT NULL CHECK(event_type IN ('appoint','change_committee','amend_order')), order_date TEXT NOT NULL DEFAULT '', order_number TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS uat_extensions (id INTEGER PRIMARY KEY AUTOINCREMENT, track_id INTEGER NOT NULL REFERENCES uat_tracks(id) ON DELETE CASCADE, sequence_no INTEGER NOT NULL, requested_days INTEGER NOT NULL DEFAULT 0, completed_work TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', new_due_date TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(track_id,sequence_no));
CREATE TABLE IF NOT EXISTS uat_subject_findings (id INTEGER PRIMARY KEY AUTOINCREMENT, track_id INTEGER NOT NULL REFERENCES uat_tracks(id) ON DELETE CASCADE, subject_id INTEGER NOT NULL REFERENCES uat_subjects(id) ON DELETE CASCADE, finding TEXT NOT NULL DEFAULT '', severity TEXT NOT NULL DEFAULT '', allegation_detail TEXT NOT NULL DEFAULT '', incident_detail TEXT NOT NULL DEFAULT '', UNIQUE(track_id,subject_id));
CREATE TABLE IF NOT EXISTS uat_decisions (id INTEGER PRIMARY KEY AUTOINCREMENT, case_id INTEGER NOT NULL REFERENCES cases(id) ON DELETE CASCADE, subject_id INTEGER NOT NULL REFERENCES uat_subjects(id) ON DELETE CASCADE, route_type TEXT NOT NULL CHECK(route_type IN ('nonserious','serious')), report_kk_date TEXT NOT NULL DEFAULT '', kk_resolution_date TEXT NOT NULL DEFAULT '', kk_resolution TEXT NOT NULL DEFAULT '', commander_decision TEXT NOT NULL DEFAULT '', order_number TEXT NOT NULL DEFAULT '', order_date TEXT NOT NULL DEFAULT '', finished_date TEXT NOT NULL DEFAULT '', UNIQUE(case_id,subject_id));
CREATE TABLE IF NOT EXISTS uat_access_assignments (bma_personal_id TEXT PRIMARY KEY, display_name TEXT NOT NULL DEFAULT '', access_role TEXT NOT NULL CHECK(access_role IN ('executive','unit_head','group_head','case_owner')), unit_level1 TEXT NOT NULL DEFAULT '', unit_level2 TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS uat_audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, case_id INTEGER, actor_id TEXT NOT NULL DEFAULT '', actor_name TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO uat_schema_migrations(version) VALUES ('001_uat');
